import subprocess
import numpy as np
from PIL import Image, ImageDraw, ImageFont
import imageio.v2 as iio
import imageio_ffmpeg
import time


class TextSpec:
    __slots__ = ("S", "siz", "x", "y", "dx", "dy", "l", "r",
                 "clr", "alpha", "fade_in_c", "fade_out_c")

    def __init__(self, S, siz, x, y, dx, dy, l, r, clr, alpha, fade_in_c, fade_out_c):
        self.S, self.siz, self.x, self.y, self.dx, self.dy = S, siz, x, y, dx, dy
        self.l, self.r, self.clr, self.alpha = l, r, clr, alpha
        self.fade_in_c, self.fade_out_c = fade_in_c, fade_out_c

    def weight_at(self, n):
        """第 n 帧总混合权重 = alpha · 淡入淡出系数，∈ [0,1]。"""
        if not (self.l <= n < self.r):
            return 0.0
        fi, fo = self.fade_in_c, self.fade_out_c
        ai = 1.0 if fi <= 0 else min(1.0, (n - self.l + 1) / fi)
        ao = 1.0 if fo <= 0 else min(1.0, (self.r - n) / fo)
        return self.alpha * ai * ao


def _build_mask(spec, font):
    """整串文字的 uint8 蒙版，返回 (mask, ox, oy)。"""
    asc, desc = font.getmetrics()
    parts = []
    for i, ch in enumerate(spec.S):
        adv = font.getlength(ch)
        x0, y0, x1, y1 = font.getbbox(ch, anchor="ls")
        lp = max(0, int(np.ceil(-x0)))
        rp = max(0, int(np.ceil(x1 - adv)))
        tp = max(0, int(np.ceil(-y0 - asc)))
        bp = max(0, int(np.ceil(y1 - desc)))
        cw, chh = int(np.ceil(adv)) + lp + rp, int(asc) + int(desc) + tp + bp
        if cw <= 0 or chh <= 0:
            continue
        img = Image.new("L", (cw, chh), 0)
        ImageDraw.Draw(img).text((lp, tp + int(asc)), ch, font=font, fill=255, anchor="ls")
        px = int(round(spec.x + i * spec.dx)) - lp
        py = int(round(spec.y + i * spec.dy)) - tp
        parts.append((px, py, np.array(img, dtype=np.uint8)))

    if not parts:
        return None
    min_x = min(p[0] for p in parts); min_y = min(p[1] for p in parts)
    max_x = max(p[0] + p[2].shape[1] for p in parts)
    max_y = max(p[1] + p[2].shape[0] for p in parts)
    mask = np.zeros((max_y - min_y, max_x - min_x), dtype=np.uint8)
    for px, py, arr in parts:
        h, w = arr.shape
        roi = mask[py - min_y: py - min_y + h, px - min_x: px - min_x + w]
        np.maximum(roi, arr, out=roi)
    return mask, min_x, min_y


def _blend(frame, m_u8, ox, oy, weight, clr):
    """frame: HxWx3 uint8 (RGB)；weight ∈ [0,1]；clr: 0xRRGGBB。"""
    if weight <= 0.0:
        return
    H, W = frame.shape[:2]
    h, w = m_u8.shape
    x0, y0 = max(0, ox), max(0, oy)
    x1, y1 = min(W, ox + w), min(H, oy + h)
    if x0 >= x1 or y0 >= y1:
        return

    target = np.array([(clr >> 16) & 0xFF, (clr >> 8) & 0xFF, clr & 0xFF],
                      dtype=np.float32)
    m = m_u8[y0 - oy: y1 - oy, x0 - ox: x1 - ox].astype(np.float32) * (weight / 255.0)
    roi = frame[y0:y1, x0:x1].astype(np.float32)
    out = roi + (target - roi) * m[..., None]
    frame[y0:y1, x0:x1] = np.clip(out + 0.5, 0, 255).astype(np.uint8)


def render_video(infile, outfile, textlst, font):
    reader = iio.get_reader(infile)
    meta = reader.get_meta_data()
    fps = float(meta.get("fps") or 30.0)
    W, H = int(meta["size"][0]), int(meta["size"][1])

    fonts = {}
    def gf(sz):
        s = max(1, int(round(sz)))
        if s not in fonts:
            fonts[s] = ImageFont.truetype(str(font), s)
        return fonts[s]

    # 约定 textlst[0] 最上层 → 逆序绘制（底层先画）
    layers = []
    for spec in reversed(textlst):
        r = _build_mask(spec, gf(spec.siz))
        if r:
            layers.append((spec, r[0], r[1], r[2]))

    ff = imageio_ffmpeg.get_ffmpeg_exe()
    cmd = [ff, "-y", "-loglevel", "error",
           "-f", "rawvideo", "-vcodec", "rawvideo",
           "-s", f"{W}x{H}", "-pix_fmt", "rgb24", "-r", str(fps),
           "-i", "pipe:0",
           "-c:v", "libx265", "-preset", "medium", "-crf", "23",
           "-pix_fmt", "yuv420p", outfile]
    proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stderr=subprocess.PIPE)

    try:
        cnt = 0
        for n, frame in enumerate(reader):
            frame = np.asarray(frame, dtype=np.uint8)
            if frame.ndim == 2:
                frame = np.stack([frame] * 3, -1)
            elif frame.shape[2] == 4:
                frame = frame[:, :, :3]
            for spec, m, ox, oy in layers:
                _blend(frame, m, ox, oy, spec.weight_at(n), spec.clr)
            proc.stdin.write(np.ascontiguousarray(frame).data)
            cnt += 1
            if cnt % 804 == 0:
                print(cnt)
                time.sleep(8)       
    finally:
        reader.close()
        try:
            proc.stdin.close()
        except Exception:
            pass
        err = proc.stderr.read().decode(errors="ignore")
        if proc.wait() != 0:
            raise RuntimeError(f"ffmpeg 失败:\n{err}")
    return outfile

caption = []

n = int(input())
in_file = input()
out_file = input()
font_name = input()

def frame(x,y):
    z=4*(x-1)+(y-1)
    return int(z*(60/64.8)*30+0.5)

for _ in range(n):
    lst = input().split()
    S = lst[0]
    siz = int(lst[1])
    x = int(lst[2])
    y = int(lst[3])
    dx = int(lst[4])
    dy = int(lst[5])
    lc = int(lst[6])
    ly = float(lst[7])
    rc = int(lst[8])
    ry = float(lst[9])
    clr = int(lst[10], 16)
    alpha = float(lst[11])
    fade_in_c = int(lst[12])
    fade_out_c = int(lst[13])

    l = frame(lc, ly)
    r = frame(rc, ry) + fade_out_c

    caption.append(TextSpec(S, siz, x, y, dx, dy, l, r, clr, alpha, fade_in_c, fade_out_c))

def priority(txt: TextSpec):
    return txt.alpha

caption.sort(key = priority)

render_video(in_file, out_file, caption, font_name)
